 * Açıklama   : Taslak/yayın sürümleri ve satıcı bilgisine bağlı ayrı hukuk onay süreci.
 */
declare(strict_types=1);
namespace Sexogate;
final class Content
{
    public function __construct(private Database $db,private Config $config){}
    public function save(array $input,Principal $actor):array
    {
        $actor->require('content',true);$kind=$input['kind']??'';$locale=$input['locale']??'';$slug=$input['slug']??'';$title=trim($input['title']??'');$summary=$input['summary']??'';$body=$input['body']??'';RuleViolation::ensure(in_array($kind,['guide','faq','collection','hero','navigation','footer','contact'],true)&&in_array($locale,['tr','en','de','ru','ar'],true)&&preg_match('/\A[a-z0-9]+(?:-[a-z0-9]+)*\z/',$slug)&&strlen($slug)<=120&&mb_strlen($title)>0&&mb_strlen($title)<=300&&mb_strlen($summary)<=2000&&mb_strlen($body)<=100000,'INVALID_CONTENT','İçerik alanlarını kontrol edin.',400);$metadata=$input['metadata']??[];RuleViolation::ensure(is_array($metadata)&&strlen($this->config->json($metadata))<=20000,'INVALID_CONTENT','İçerik ayrıntıları geçersiz.',400);
        return $this->db->transaction(function()use($input,$actor,$kind,$locale,$slug,$title,$summary,$body,$metadata){$id=$input['id']??Database::id();$entry=isset($input['id'])?$this->db->one('SELECT * FROM content_entries WHERE id=? FOR UPDATE',[$id]):null;if(isset($input['id']))RuleViolation::ensure($entry&&$entry['kind']===$kind&&$entry['locale']===$locale&&$entry['slug']===$slug,'CONTENT_IDENTITY_MISMATCH','Dil/tür/bağlantı değiştirmek için ayrı içerik oluşturun.');else $this->db->execute('INSERT INTO content_entries(id,kind,locale,slug) VALUES(?,?,?,?)',[$id,$kind,$locale,$slug]);$version=(int)($entry['current_version']??0)+1;$this->db->execute('INSERT INTO content_revisions(entry_id,version,title,summary,body,metadata,actor_id) VALUES(?,?,?,?,?,?,?)',[$id,$version,$title,$summary,$body,$this->config->json($metadata),$actor->id]);$this->db->execute('UPDATE content_entries SET current_version=? WHERE id=?',[$version,$id]);(new Audit($this->db))->record($actor,'draft','content',$id,['version'=>$version]);return ['id'=>$id,'version'=>$version];});
    }
    public function publish(string $id,Principal $actor,?string $publishAt=null):array
    {$actor->require('content',true);$at=$publishAt===null?new \DateTimeImmutable('now',new \DateTimeZone('UTC')):new \DateTimeImmutable($publishAt);return $this->db->transaction(function()use($id,$actor,$at){$entry=$this->db->one('SELECT * FROM content_entries WHERE id=? FOR UPDATE',[$id]);RuleViolation::ensure($entry&&!(bool)$entry['archived']&&in_array($entry['locale'],['tr','en'],true),'CONTENT_NOT_PUBLISHABLE','İçerik arşivlenmiş veya dil yayını tamamlanmamış.');$this->db->execute('INSERT INTO content_publications(entry_id,version,publish_at,actor_id) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE version=version',[$id,$entry['current_version'],$at->setTimezone(new \DateTimeZone('UTC'))->format('Y-m-d H:i:s.u'),$actor->id]);(new Audit($this->db))->record($actor,'publish','content',$id,['version'=>$entry['current_version']]);return ['id'=>$id,'version'=>(int)$entry['current_version']];});}
    public function archive(string $id,Principal $actor):void
    {$actor->require('content',true);$this->db->transaction(function()use($id,$actor){RuleViolation::ensure($this->db->execute('UPDATE content_entries SET archived=true WHERE id=?',[$id])===1,'CONTENT_NOT_FOUND','İçerik bulunamadı.',404);(new Audit($this->db))->record($actor,'archive','content',$id);});}
    public function listing(string $kind,string $locale):array
    {$rows=$this->db->all('SELECT e.id,e.kind,e.locale,e.slug,r.title,r.summary,r.body,r.metadata,p.publish_at FROM content_entries e JOIN content_publications p ON p.entry_id=e.id JOIN content_revisions r ON r.entry_id=p.entry_id AND r.version=p.version WHERE e.kind=? AND e.locale=? AND e.archived=false AND p.publish_at<=CURRENT_TIMESTAMP(3) AND NOT EXISTS(SELECT 1 FROM content_publications later WHERE later.entry_id=p.entry_id AND later.publish_at<=CURRENT_TIMESTAMP(3) AND(later.publish_at>p.publish_at OR(later.publish_at=p.publish_at AND later.version>p.version))) ORDER BY p.publish_at DESC,e.id LIMIT 100',[$kind,$locale]);foreach($rows as &$r)$r['metadata']=json_decode($r['metadata'],true);return $rows;}
    public function find(string $kind,string $slug,string $locale):?array
    {$row=$this->db->one('SELECT e.id,e.kind,e.locale,e.slug,r.title,r.summary,r.body,r.metadata,p.publish_at FROM content_entries e JOIN content_publications p ON p.entry_id=e.id JOIN content_revisions r ON r.entry_id=p.entry_id AND r.version=p.version WHERE e.kind=? AND e.locale=? AND e.slug=? AND e.archived=false AND p.publish_at<=CURRENT_TIMESTAMP(3) ORDER BY p.publish_at DESC,p.version DESC LIMIT 1',[$kind,$locale,$slug]);if($row)$row['metadata']=json_decode($row['metadata'],true);return $row;}
    public function admin(Principal $actor):array
    {$actor->require('content');return $this->db->all('SELECT e.id,e.kind,e.locale,e.slug,e.current_version,e.archived,r.title,r.summary,r.body FROM content_entries e JOIN content_revisions r ON r.entry_id=e.id AND r.version=e.current_version ORDER BY e.created_at DESC LIMIT 100');}
    private function seller():array
    {$seller=[];foreach(['seller.name','seller.taxNumber','seller.address','seller.supportEmail','seller.phone','seller.bankAccount'] as $key){$r=$this->db->one('SELECT value FROM settings WHERE `key`=?',[$key]);$v=$r?json_decode($r['value'],true):null;RuleViolation::ensure(is_string($v)&&trim($v)!=='','SELLER_NOT_CONFIGURED','Hukuk onayı için gerçek satıcı bilgileri tamamlanmalıdır.');$seller[$key]=$v;}return $seller;}
    public function legalDraft(string $kind,string $locale,string $title,string $body,Principal $actor):array
    {$actor->require('settings',true);RuleViolation::ensure(preg_match('/\A[a-z-]{2,64}\z/',$kind)&&in_array($locale,['tr','en','de','ru','ar'],true)&&mb_strlen(trim($title))>0&&mb_strlen($title)<=300&&mb_strlen(trim($body))>=5&&mb_strlen($body)<=100000,'INVALID_LEGAL','Hukuk metni alanlarını kontrol edin.',400);return $this->db->transaction(function()use($kind,$locale,$title,$body,$actor){$this->db->one("SELECT name FROM commerce_definition_locks WHERE name='php-legal' FOR UPDATE");$n=(int)$this->db->one('SELECT COALESCE(MAX(version),0) n FROM legal_documents WHERE kind=? AND locale=?',[$kind,$locale])['n']+1;$id=Database::id();$this->db->execute("INSERT INTO legal_documents(id,kind,locale,version,title,body,body_hash,status) VALUES(?,?,?,?,?,?,?,'draft')",[$id,$kind,$locale,$n,$title,$body,hash('sha256',$body)]);(new Audit($this->db))->record($actor,'draft','legal_documents',$id,['version'=>$n]);return ['id'=>$id,'version'=>$n];});}
    public function approveLegal(string $id,string $reference,Principal $actor):array
    {$actor->require('settings',true);RuleViolation::ensure(mb_strlen(trim($reference))>=10&&mb_strlen($reference)<=2000,'LEGAL_REFERENCE_REQUIRED','Yetkili hukuk incelemesi referansı gerekir.',400);return $this->db->transaction(function()use($id,$reference,$actor){$seller=$this->seller();$r=$this->db->one('SELECT * FROM legal_documents WHERE id=? FOR UPDATE',[$id]);RuleViolation::ensure($r&&$r['status']==='draft'&&hash_equals($r['body_hash'],hash('sha256',$r['body'])),'LEGAL_STATE','Metin taslak ve bütünlüğü doğrulanmış olmalıdır.');$this->db->execute("UPDATE legal_documents SET status='approved',approved_by=?,review_reference=?,seller_snapshot=?,approved_at=CURRENT_TIMESTAMP(3) WHERE id=?",[$actor->id,$reference,$this->config->json($seller),$id]);(new Audit($this->db))->record($actor,'approve','legal_documents',$id);return ['id'=>$id,'status'=>'approved'];});}
    private function sameSeller(string $snapshot,array $seller):bool
    {$old=json_decode($snapshot,true);if(!is_array($old))return false;ksort($old,SORT_STRING);ksort($seller,SORT_STRING);return $old===$seller;}
    public function publishLegal(string $id,Principal $actor):array
    {$actor->require('settings',true);return $this->db->transaction(function()use($id,$actor){$this->db->one("SELECT name FROM commerce_definition_locks WHERE name='php-legal' FOR UPDATE");$seller=$this->seller();$r=$this->db->one('SELECT * FROM legal_documents WHERE id=? FOR UPDATE',[$id]);RuleViolation::ensure($r&&$r['status']==='approved'&&$r['approved_by']&&$r['review_reference']&&$this->sameSeller($r['seller_snapshot'],$seller)&&in_array($r['locale'],['tr','en'],true),'LEGAL_NOT_APPROVED','Satıcı bilgileriyle eşleşen hukuk onayı ve tamamlanmış dil gerekir.');$this->db->execute("UPDATE legal_documents SET status='archived' WHERE kind=? AND locale=? AND status='effective'",[$r['kind'],$r['locale']]);$this->db->execute("UPDATE legal_documents SET status='effective',effective_at=CURRENT_TIMESTAMP(3) WHERE id=?",[$id]);(new Audit($this->db))->record($actor,'publish','legal_documents',$id);return ['id'=>$id,'status'=>'effective'];});}
}
